{
    let invalid = &b"invalid input\n"[..];
    let overflow = &b"arithmetic overflow\n"[..];
    let zero_divisor = &b"division by zero\n"[..];

    let result = 'calculate: {
        let mut record: Vec<u8> = b"".to_vec();
        let mut buffer = [0_u8; 4096];
        loop {
            let count = read(0, &mut buffer, 4096);
            if count == -EINTR {
                continue;
            }
            if count < 0 {
                break 'calculate (None, invalid);
            }
            if count == 0 {
                break;
            }
            let chunk = &buffer[..count as Usize];
            if let Some(end) = chunk.iter().position(|&byte| byte == b'\n') {
                record.extend_from_slice(&chunk[..end]);
                break;
            }
            record.extend_from_slice(chunk);
        }

        let mut tokens = record
            .split(|&byte| byte == b' ' || byte == b'\t' || byte == b'\r')
            .filter(|token| !token.is_empty());
        let (Some(left), Some(operator), Some(right), None) =
            (tokens.next(), tokens.next(), tokens.next(), tokens.next())
        else {
            break 'calculate (None, invalid);
        };
        let mut operands = [0_i64; 2];
        for (operand, token) in operands.iter_mut().zip([left, right]) {
            let (digits, negative) = match token {
                [b'-', digits @ ..] => (digits, true),
                [b'+', digits @ ..] => (digits, false),
                digits => (digits, false),
            };
            if digits.is_empty() {
                break 'calculate (None, invalid);
            }
            for &byte in digits {
                if !byte.is_ascii_digit() {
                    break 'calculate (None, invalid);
                }
                let digit = (byte - b'0') as i64;
                let value = operand.checked_mul(10).and_then(|prefix| {
                    if negative { prefix.checked_sub(digit) } else { prefix.checked_add(digit) }
                });
                let Some(value) = value else {
                    break 'calculate (None, invalid);
                };
                *operand = value;
            }
        }

        let [left, right] = operands;
        let value = match operator {
            b"+" => left.checked_add(right),
            b"-" => left.checked_sub(right),
            b"*" => left.checked_mul(right),
            b"/" if right == 0 => break 'calculate (None, zero_divisor),
            b"/" => left.checked_div(right),
            _ => break 'calculate (None, invalid),
        };
        (value, overflow)
    };

    // An I64 needs at most 19 digits, one sign and one line feed.
    let mut decimal = [0_u8; 21];
    let (fd, output, status) = match result {
        (Some(value), _) => {
            let mut magnitude = value.unsigned_abs();
            let mut start = decimal.len() - 1;
            decimal[start] = b'\n';
            loop {
                start -= 1;
                decimal[start] = b'0' + (magnitude % 10) as u8;
                magnitude /= 10;
                if magnitude == 0 {
                    break;
                }
            }
            if value < 0 {
                start -= 1;
                decimal[start] = b'-';
            }
            (1, &decimal[start..], 0)
        }
        (None, diagnostic) => (2, diagnostic, 1),
    };

    let mut sent = 0;
    while sent < output.len() {
        let count = write(fd, &output[sent..], output.len() - sent);
        if count == -EINTR {
            continue;
        }
        if count <= 0 {
            return 1;
        }
        sent += count as Usize;
    }
    status
}
